import importlib.metadata as metadata
from pathlib import Path
import cv2,numpy as np
from context import ROOT,SOURCE,STUDY,read,write,sha
from core import FAMILY,detect,square_points,hypotheses

def main():
    assert not STUDY.exists();STUDY.mkdir();prior=STUDY.parent/'rgb_baseline_v1';assert (prior/'summary.json').exists();module=Path(cv2.__file__).parent;binaries=list(module.glob('*.pyd'));assert binaries
    write(STUDY/'test-plan.json',dict(question='Can the already-installed pinned OpenCV fiducial frontend and square PnP solver pass isolated image/pose/frame controls before any native tagged-object trial?',scope='Zero native launches. Generated2Dtag image detection and manufactured projected-corner math only. No robot images,actual task detections,calibrated sigma,tagged-Cube operating envelope or sensed control is qualified.',assumptions='Use OpenCV4.11.0 already installed,DICT_APRILTAG_36h11,16mm nominal tag edge and declared CV right/down/forward frame. Registry tag-to-Cube transforms are separate future inputs. Tag edge/calibration are software assumptions;hardware measurements remain deferred.',gates='Generate/decode known marker and blank image;retain all positive-depth IPPE_SQUARE hypotheses with exact ordered corners;check known pose and full transform composition;reject malformed/nonfinite/reversed corners. Demonstrate cyclic corner relabeling can preserve reprojection while changing pose. Do not pick planar ambiguity using ground truth or synthesize detector confidence/sigma.',dependency=dict(opencv_version=cv2.__version__,numpy_version=np.__version__,opencv_module=str(module),binary_sha256={str(p):sha(p) for p in binaries},distributions={n:metadata.version(n) for n in ['opencv-python'] if metadata.packages_distributions().get('cv2') and metadata.version(n)}),prior_summary_sha256=sha(prior/'summary.json'),assembly_deferred=True))
    marker=cv2.aruco.generateImageMarker(cv2.aruco.getPredefinedDictionary(FAMILY),7,256);image=np.full((384,384,3),255,dtype=np.uint8);image[64:320,64:320]=marker[:,:,None];cv2.imwrite(str(STUDY/'manufactured-tag.png'),image);detected=detect(image.tobytes(),384,384);blank=detect(bytes([255])*384*384*3,384,384);K=np.array([[457.,0,320],[0,457.,240],[0,0,1.]]);rv=np.array([2.8,.1,.05]);tv=np.array([.001,-.002,.12]);corners=cv2.projectPoints(square_points(.016),rv,tv,K,np.zeros(5))[0].reshape(4,2);poses=hypotheses(corners,K,.016)
    write(STUDY/'summary.json',dict(simulator_runs=0,results=[dict(kind='manufactured_generated_image',detection=detected),dict(kind='manufactured_blank_image',detection=blank),dict(kind='manufactured_projected_corners',candidates=poses,expected_rotation=cv2.Rodrigues(rv)[0].tolist(),expected_translation_m=tv.tolist(),corners_px=corners.tolist())],fiducial_math_prepared=True,camera_perception_admitted=False,sensed_controller_admitted=False,full_m2_admitted=False))
if __name__=='__main__':main()
